// Descriptive decoder names inferred from the context fields they access.
int32_t XmaDecoder_HasInputSpace(void* decoder, uint32_t stream); // @ 0x8246B050
int32_t XmaDecoder_IsBufferPending(void* decoder, uint32_t stream, const void* data); // @ 0x8246AFF0
uint32_t XmaDecoder_GetStreamStatus(void* decoder, uint32_t stream); // @ 0x8246B488
int32_t XmaDecoder_IsInputEmpty(void* decoder, uint32_t stream); // @ 0x8246B0B8
int32_t XmaDecoder_SubmitData(void* decoder, uint32_t stream, const void* data, uint32_t bytes); // @ 0x8246AF18
int32_t XmaDecoder_SetReadPosition(void* decoder, uint32_t stream, uint32_t bits, uint32_t subframe); // @ 0x8246B5E0
int32_t XmaDecoder_SetLoopRegion(void* decoder, uint32_t stream, const XmaLoopRegion* region); // @ 0x8246B4D8

static void xaudioAcquireLock(XAudioLock& lock) {
    uint32_t irql = KeRaiseIrqlToDpcLevel();
    if (lock.depth == 0 || lock.owner != g_sda_base) {
        KeAcquireSpinLockAtRaisedIrql(&lock.spin);
        lock.owner = g_sda_base;
        lock.oldIrql = static_cast<uint8_t>(irql);
    }
    ++lock.depth;
}

static void xaudioReleaseLock(XAudioLock& lock) {
    if (lock.depth != 0 && lock.owner == g_sda_base) {
        if (--lock.depth == 0) {
            uint32_t irql = lock.oldIrql;
            lock.owner = nullptr;
            lock.oldIrql = 0;
            KeReleaseSpinLockFromRaisedIrql(&lock.spin);
            KfLowerIrql(irql);
        }
    }
}

static XmaSourceBuffer* nextBuffer(XmaSourceLayout* self, XmaSourceBuffer* buffer) {
    auto* sentinel = &self->buffers;
    auto* link = buffer ? reinterpret_cast<SourceLink*>(reinterpret_cast<uint8_t*>(buffer) + self->linkOffset)
                        : sentinel;
    return link->next == sentinel ? nullptr
        : reinterpret_cast<XmaSourceBuffer*>(reinterpret_cast<uint8_t*>(link->next) - self->linkOffset);
}

// Submit queued input and retire completed buffers. Called with the source lock
// already held; completion callbacks run with one level of both locks released.
// ke_7278 is autogenerated; this name describes the observed SDK operation.
int32_t XmaSource_SubmitBuffers(XmaSourceLayout* self) { // @ 0x82467278
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        if (!XmaDecoder_HasInputSpace(self->decoder, i)) return 1;
    }

    bool queued = false;
    xaudioAcquireLock(g_xaudioSourceLock);
    for (auto* buffer = nextBuffer(self, nullptr); buffer;) {
        if (buffer->link.next == &buffer->link) break;
        auto* next = nextBuffer(self, buffer); // callbacks may unlink/free buffer
        if (buffer->state) {
            bool pending = false;
            for (uint8_t i = 0; i < self->streamCount; ++i) {
                if (XmaDecoder_IsBufferPending(self->decoder, i, buffer->data)
                    && !(XmaDecoder_GetStreamStatus(self->decoder, i) & 8)) {
                    pending = true;
                    break;
                }
            }
            if (!pending) buffer->state = 4;
        } else {
            queued = true;
        }
        // Keep the final completed buffer while the source is still playing.
        if (buffer->state == 4 && (next || !(self->flags & 1) || (self->flags & 16))) {
            xaudioReleaseLock(g_xaudioSourceLock);
            xaudioReleaseLock(self->lock);
            using CompleteFn = void (*)(void*, void*, uint32_t);
            reinterpret_cast<CompleteFn>(self->sourceVtable[19])(&self->sourceVtable, buffer, 0);
            xaudioAcquireLock(self->lock);
            xaudioAcquireLock(g_xaudioSourceLock);
        }
        buffer = next;
    }
    xaudioReleaseLock(g_xaudioSourceLock);

    if (queued) {
        xaudioAcquireLock(g_xaudioSourceLock);
        for (auto* buffer = nextBuffer(self, nullptr); buffer;) {
            if (buffer->link.next == &buffer->link) break;
            auto* next = nextBuffer(self, buffer);
            if (buffer->state == 0) {
                bool space = true;
                for (uint8_t i = 0; i < self->streamCount; ++i) {
                    bool empty = i != 0 && XmaDecoder_IsInputEmpty(self->decoder, i);
                    XmaDecoder_SubmitData(self->decoder, i, buffer->data, buffer->bytes);
                    if (empty) XmaDecoder_SetReadPosition(self->decoder, i, (uint32_t(i) << 14) + 32, 0);
                    if (buffer->loopCount) {
                        XmaLoopRegion loop{};
                        loop.startBits = buffer->loops[i].startBits;
                        loop.endBits = buffer->loops[i].endBits;
                        loop.startSubframe = buffer->loops[i].startSubframe;
                        loop.endSubframe = buffer->loops[i].endSubframe;
                        loop.count = static_cast<uint8_t>(buffer->loopCount);
                        XmaDecoder_SetLoopRegion(self->decoder, i, &loop);
                    }
                    if (!XmaDecoder_HasInputSpace(self->decoder, i)) space = false;
                }
                buffer->state = 3;
                if (!space) break; // finish every stream before stopping the queue
            }
            buffer = next;
        }
        xaudioReleaseLock(g_xaudioSourceLock);
    }

    if (self->pendingPosition[0].bits) {
        for (uint8_t i = 0; i < self->streamCount; ++i) {
            XmaDecoder_SetReadPosition(self->decoder, i, self->pendingPosition[i].bits,
                                      self->pendingPosition[i].subframe >> 7);
        }
        self->pendingPosition[0].bits = 0; // only the first word is the pending marker
    }
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        if (!XmaDecoder_IsInputEmpty(self->decoder, i)
            && !(XmaDecoder_GetStreamStatus(self->decoder, i) & 8)) return 1;
    }
    return 0;
}

// Render one 256-frame planar float block, padding underruns and retiring buffers.
// r4 is unused; r5 is the output frame interface. This is vtable slot 56 of
// 0x82005a60, not a physics update. Locks are explicitly dropped around callbacks.
int32_t XmaSource_Render(XmaSourceLayout* self, void*, void* output) { // @ 0x82467D90
    auto setFlags = [self](uint32_t mask, uint32_t value) {
        using Fn = void (*)(void*, uint32_t, uint32_t);
        reinterpret_cast<Fn>(self->sourceVtable[17])(&self->sourceVtable, mask, value);
    };
    auto stop = [self]() {
        using Fn = void (*)(void*, uint32_t);
        reinterpret_cast<Fn>(self->vtable[11])(self, 1);
    };
    xaudioAcquireLock(self->lock);
    if (!XmaDecoder_IsEnabled(self->decoder)) {
        xaudioReleaseLock(self->lock);
        return 0;
    }
    int32_t result = XmaDecoder_Lock(self->decoder);
    if (result < 0) {
        xaudioReleaseLock(self->lock);
        return result;
    }

    xaudioAcquireLock(g_xaudioSourceLock);
    AudioFrame frame;
    result = XAudioFrame_Get(output, &frame);
    if (result >= 0) {
        uint32_t channels = 0;
        for (uint8_t i = 0; i < self->streamCount; ++i) channels += self->formats[i].channels;
        frame.channels = static_cast<uint8_t>(channels);
        result = XAudioFrame_Resize(output, &frame, 1);
    }
    if (result < 0) {
        xaudioReleaseLock(g_xaudioSourceLock);
        xaudioReleaseLock(self->lock);
        return result;
    }
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        auto& stream = self->streams[i];
        stream.output = frame.samples;
        stream.outputFrames = 256;
        stream.outputOffset = 0;
        frame.samples += self->formats[i].channels * 256;
    }

    if (!(self->flags & 1) || (self->flags & 16)) {
        for (uint8_t i = 0; i < self->streamCount; ++i) {
            auto& stream = self->streams[i];
            for (uint32_t channel = 0; channel < stream.channels; ++channel) {
                std::memset(stream.output + channel * 256, 0, stream.outputFrames * sizeof(float));
            }
        }
        xaudioReleaseLock(g_xaudioSourceLock);
        xaudioReleaseLock(self->lock);
        return 1;
    }
    if (self->flags & 2) {
        for (uint8_t i = 0; i < self->streamCount; ++i) {
            auto& stream = self->streams[i];
            stream.gain = self->gain;
            stream.previousGain = stream.gain;
            for (auto& value : stream.filterHistory) value = 0;
            stream.filterGain = 0.0f;
        }
        setFlags(2, 0);
    }
    if (self->flags & 4) {
        --self->fadeTicks; // uint16 wrap is intentional, including zero -> 65535.
        float gain = self->fadeTicks ? self->streams[0].gain * g_xmaFadeScale : 0.0f;
        for (uint8_t i = 0; i < self->streamCount; ++i) self->streams[i].gain = gain;
    }
    xaudioReleaseLock(g_xaudioSourceLock);

    XmaDecoder_Wait(self->decoder);
    uint32_t silence = 0;
    bool refill = false;
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        uint32_t available = XmaDecoder_Available(self->decoder, i);
        uint32_t consumed = 0;
        const void* input;
        if (available) {
            uint32_t count = XmaDecoder_Peek(self->decoder, i, &input);
            while (count) {
                auto& stream = self->streams[i];
                stream.input = input;
                stream.inputFrames = count;
                stream.inputOffset = 0;
                uint32_t processed = XmaRenderStream_Process(&stream);
                consumed += processed;
                XmaDecoder_Consume(self->decoder, i, processed, &input);
                if (self->streams[i].outputFrames == self->streams[i].outputOffset) break;
                count = XmaDecoder_Peek(self->decoder, i, &input);
            }
        }
        if (available - consumed <= self->refillThreshold[i]) refill = true;
        self->samplesPlayed = XmaDecoder_SamplesPlayed(self->decoder, 0);
        auto& stream = self->streams[i];
        uint32_t remaining = stream.outputFrames - stream.outputOffset;
        if (remaining) {
            // r26 holds the byte count in the channel loop, then becomes 1.
            for (uint32_t channel = 0; channel < stream.channels; ++channel) {
                std::memset(stream.output + stream.outputOffset + channel * 256, 0, remaining * sizeof(float));
            }
            silence = 1;
        }
    }
    int32_t submitted = XmaSource_SubmitBuffers(self);
    xaudioAcquireLock(g_xaudioSourceLock);
    for (uint8_t i = 0; i < self->streamCount; ++i) self->streams[i].previousGain = self->streams[i].gain;

    if (silence) {
        if (!(self->flags & 8)) {
            bool pending = false;
            for (auto* buffer = nextBuffer(self, nullptr); buffer; buffer = nextBuffer(self, buffer)) {
                pending |= buffer->state != 4;
            }
            if (!pending) setFlags(16, 16);
        } else if (submitted == 0 && !(self->flags & 16)) {
            stop();
        }
    }
    if ((self->flags & 4) && (self->fadeTicks == 0 || (self->flags & 16))) stop();

    if (!(self->flags & 1) || (self->flags & 16)) {
        for (auto* buffer = nextBuffer(self, nullptr); buffer;) {
            auto* current = buffer;
            buffer = nextBuffer(self, buffer); // callbacks may unlink/free current
            if (current->state != 4) continue;
            xaudioReleaseLock(g_xaudioSourceLock);
            xaudioReleaseLock(self->lock);
            using Fn = void (*)(void*, void*, uint32_t);
            reinterpret_cast<Fn>(self->sourceVtable[19])(&self->sourceVtable, current, 0);
            xaudioAcquireLock(self->lock);
            xaudioAcquireLock(g_xaudioSourceLock);
        }
    }
    xaudioReleaseLock(g_xaudioSourceLock);
    if (refill && XmaDecoder_IsEnabled(self->decoder)) {
        result = XmaDecoder_Unlock(self->decoder);
        if (result < 0) {
            xaudioReleaseLock(self->lock);
            return result;
        }
    }
    xaudioReleaseLock(self->lock);
    return 0;
}

// Software PCM sibling of XmaSource: the common source prefix ends at +0xb4,
// where this variant embeds its renderer instead of an XMA decoder pointer.
struct PcmSourceBuffer {
    SourceLink link;
    const void* data;
    uint32_t frames;
    uint32_t loopCount;                     // UINT32_MAX means infinite
    uint32_t loopStart;
    uint32_t loopFrames;
    uint8_t pad1c[64];
    void* context;                          // +0x5c: loop callback payload
};

struct PcmSourceEvent {
    void* sourceContext;
    void* bufferContext;
    uint32_t reserved;
};

struct PcmSourceLayout {
    void** vtable;
    uint8_t pad04[8];
    void* context;                          // +0x0c
    void** sourceVtable;                    // +0x10
    SourceLink buffers;                     // +0x14
    uint32_t linkOffset;                    // +0x1c
    uint8_t pad20[20];
    uint8_t channels;                       // +0x34
    uint8_t pad35[55];
    float gain;                            // +0x6c
    uint8_t pad70[4];
    uint32_t position;                      // +0x74: frame within current buffer
    uint8_t pad78[44];
    uint32_t samplesPlayed;                 // +0xa4
    uint8_t flags;                          // +0xa8
    uint8_t padA9;
    uint16_t fadeTicks;                     // +0xaa
    uint8_t padAC[4];
    void (*loopCallback)(const PcmSourceEvent*); // +0xb0
    XmaRenderStream stream;                 // +0xb4
};

#if UINTPTR_MAX == UINT32_MAX
static_assert(sizeof(PcmSourceBuffer) == 96);
static_assert(sizeof(PcmSourceEvent) == 12);
static_assert(offsetof(PcmSourceLayout, channels) == 52);
static_assert(offsetof(PcmSourceLayout, gain) == 108);
static_assert(offsetof(PcmSourceLayout, position) == 116);
static_assert(offsetof(PcmSourceLayout, samplesPlayed) == 164);
static_assert(offsetof(PcmSourceLayout, loopCallback) == 176);
static_assert(offsetof(PcmSourceLayout, stream) == 180);
static_assert(sizeof(PcmSourceLayout) == 268);
#endif

int32_t PcmFrame_Get(void* owner, AudioFrame* frame); // @ 0x82465D80
int32_t PcmFrame_Resize(void* owner, const AudioFrame* frame, uint32_t flags); // @ 0x82465EF0

// Descriptive SDK name, not a recovered symbol. Previously ph_vt5B98_36_91C0.
// Render 256 planar float frames, looping and completing queued PCM buffers.
// r4 is unused; r5 is an interface at +8 in its buffer owner. Loop/completion
// callbacks run outside this function's global-lock level and may alter the queue.
int32_t PcmSource_Render(PcmSourceLayout* self, void*, void* output) { // @ 0x824691C0
    auto firstBuffer = [self]() -> PcmSourceBuffer* {
        auto* sentinel = &self->buffers;
        return sentinel->next == sentinel ? nullptr
            : reinterpret_cast<PcmSourceBuffer*>(
                reinterpret_cast<uint8_t*>(sentinel->next) - self->linkOffset);
    };
    auto setFlags = [self](uint32_t mask, uint32_t value) {
        using Fn = void (*)(void*, uint32_t, uint32_t);
        reinterpret_cast<Fn>(self->sourceVtable[17])(&self->sourceVtable, mask, value);
    };
    auto stop = [self]() {
        using Fn = void (*)(void*, uint32_t);
        reinterpret_cast<Fn>(self->vtable[11])(self, 1);
    };
    auto silence = [self]() {
        auto& stream = self->stream;
        uint32_t remaining = stream.outputFrames - stream.outputOffset;
        if (remaining) {
            for (uint32_t channel = 0; channel < stream.channels; ++channel) {
                std::memset(stream.output + stream.outputOffset + channel * 256,
                            0, remaining * sizeof(float));
            }
        }
    };

    void* owner = output ? static_cast<uint8_t*>(output) - 8 : nullptr;
    xaudioAcquireLock(g_xaudioSourceLock);
    AudioFrame frame;
    int32_t result = PcmFrame_Get(owner, &frame);
    if (result >= 0) {
        frame.channels = self->channels;
        result = PcmFrame_Resize(owner, &frame, 1);
    }
    if (result < 0) {
        xaudioReleaseLock(g_xaudioSourceLock);
        return result;
    }
    auto& stream = self->stream;
    stream.output = frame.samples;
    stream.outputFrames = 256;
    stream.outputOffset = 0;
    if (!(self->flags & 1) || (self->flags & 16)) {
        silence();
        xaudioReleaseLock(g_xaudioSourceLock);
        return 1;
    }
    if (self->flags & 2) {
        stream.gain = self->gain;
        stream.previousGain = stream.gain;
        for (auto& value : stream.filterHistory) value = 0;
        stream.filterGain = 0.0f;
        setFlags(2, 0);
    }
    if (self->flags & 4) {
        --self->fadeTicks; // wrapping uint16, including 0 -> 65535
        stream.gain = self->fadeTicks ? stream.gain * g_xmaFadeScale : 0.0f;
    }
    xaudioReleaseLock(g_xaudioSourceLock);

    PcmSourceBuffer* buffer = nullptr;
    for (;;) {
        if (buffer && stream.inputFrames == stream.inputOffset) {
            if (buffer->loopCount) {
                if (buffer->loopCount != UINT32_MAX) --buffer->loopCount;
                self->position = buffer->loopStart;
                if (self->loopCallback) {
                    PcmSourceEvent event{self->context, buffer->context, 0};
                    self->loopCallback(&event);
                }
            } else {
                using Fn = void (*)(void*, void*, uint32_t);
                reinterpret_cast<Fn>(self->sourceVtable[19])(&self->sourceVtable, buffer, 0);
                buffer = nullptr; // callback may have unlinked/freed this buffer
            }
        }
        if (stream.outputFrames == stream.outputOffset) break;
        if (!buffer) {
            xaudioAcquireLock(g_xaudioSourceLock);
            buffer = firstBuffer();
            xaudioReleaseLock(g_xaudioSourceLock);
        }
        if (!buffer) break;
        uint32_t end = buffer->loopCount ? buffer->loopStart + buffer->loopFrames : buffer->frames;
        stream.input = buffer->data;
        stream.inputFrames = end;
        stream.inputOffset = self->position < end ? self->position : end;
        uint32_t processed = XmaRenderStream_Process(&stream);
        self->position += processed;
        self->samplesPlayed += processed;
    }

    xaudioAcquireLock(g_xaudioSourceLock);
    stream.previousGain = stream.gain;
    if (stream.outputFrames != stream.outputOffset) {
        silence();
        if (!(self->flags & 8)) {
            if (!firstBuffer()) setFlags(16, 16);
        } else {
            stop();
        }
    }
    if ((self->flags & 4) && (self->fadeTicks == 0 || (self->flags & 16))) stop();
    xaudioReleaseLock(g_xaudioSourceLock);
    return 0;
}
